const result = $json;
const skipped = result.skipped ? `⏭️ Skipped: ${result.skipped}` : '';
const alertSent = result.alert_sent === true ? `✅ Alert sent: ${result.message}` : '';
const noAlert = result.alert_sent === false && !result.skipped ? `✓ 비용 정상: $${result.today_usd?.toFixed(2) || '0.00'} / $${result.threshold_usd?.toFixed(2) || '5.00'}` : '';
const error = result.error ? `❌ Error: ${result.error}` : '';
const webhookError = result.webhook_error ? `⚠️ Webhook error: ${result.webhook_error}` : '';

const text = [skipped, alertSent, noAlert, error, webhookError].filter(s => s).join('\n') || '처리됨';

return [{ json: { text, success: true, alert_sent: result.alert_sent, today_usd: result.today_usd, threshold_usd: result.threshold_usd } }];
